  const downloadReloadTimerRef = useRef(null);

  // Initialize and listen to Google Drive Auth & Sync events
  useEffect(() => {
    getGoogleDriveAuthState().then(state => {
      setGdriveAuthState(state);
      if (state?.accessToken) {
        // Fast background check on boot
        syncWithGoogleDrive({
          force: false,
          interactive: false,
          onConflict: (conflict) => setGdriveConflictData(conflict)
        }).catch(err => console.warn('[App] Boot sync error:', err));
      }
    });

    const handleAuthChanged = (e) => {
      setGdriveAuthState(e.detail);
    };

    const handleSyncStatus = (e) => {
      const { status, message, step, total, mediaProgress } = e.detail || {};
      if (status === 'syncing') {
        setGdriveSyncState({
          isSyncing: true,
          step: step || 0,
          total: total || 10,
          message: message || 'Syncing...',
          mediaProgress: mediaProgress || null
        });
      } else if (status === 'synced') {
        setGdriveSyncState({ isSyncing: false, step: 0, total: 0, message: message || 'In sync', mediaProgress: null });
        setJustSynced(true);
        if (justSyncedTimerRef.current) clearTimeout(justSyncedTimerRef.current);
        justSyncedTimerRef.current = setTimeout(() => {
          setJustSynced(false);
        }, 2800);
      } else if (status === 'error' || status === 'cancelled') {
        setGdriveSyncState({ isSyncing: false, step: 0, total: 0, message: '', mediaProgress: null });
      }
    };

    window.addEventListener('gdrive-auth-changed', handleAuthChanged);
    window.addEventListener('gdrive-sync-status', handleSyncStatus);

    return () => {
      window.removeEventListener('gdrive-auth-changed', handleAuthChanged);
      window.removeEventListener('gdrive-sync-status', handleSyncStatus);
    };
  }, []);

