  // Audio Feedback Chimes using Web Audio API
  const playStateChangeSound = (type = 'click') => {
    try {
      const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      const osc = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      osc.connect(gain);
      gain.connect(audioCtx.destination);
      const now = audioCtx.currentTime;

      if (type === 'start' || type === 'resume') {
        osc.frequency.setValueAtTime(523.25, now); // C5
        osc.frequency.exponentialRampToValueAtTime(783.99, now + 0.15); // G5
        gain.gain.setValueAtTime(0.08, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.18);
        osc.start(now);
        osc.stop(now + 0.18);
      } else if (type === 'pause') {
        osc.frequency.setValueAtTime(783.99, now); // G5
        osc.frequency.exponentialRampToValueAtTime(523.25, now + 0.15); // C5
        gain.gain.setValueAtTime(0.08, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.18);
        osc.start(now);
        osc.stop(now + 0.18);
      } else if (type === 'reset') {
        osc.frequency.setValueAtTime(329.63, now); // E4
        gain.gain.setValueAtTime(0.06, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.08);
        osc.start(now);
        osc.stop(now + 0.08);
      }
    } catch (e) {
      console.error("Web Audio API state sound failed:", e);
    }
  };

  const getLiveTodayHours = () => {
    let activeExtra = 0;
    if (timerState.pomodoroStatus === 'running' && timerState.pomodoroMode === 'study') {
      const elapsed = Math.floor((Date.now() - (timerState.pomodoroStartedAt || Date.now())) / 1000);
      activeExtra = Math.min(timerState.pomodoroDuration || 1500, elapsed) / 3600;
    } else if (timerState.timerStatus === 'running') {
      const elapsed = Math.floor((Date.now() - (timerState.timerStartedAt || Date.now())) / 1000);
      activeExtra = Math.min(timerState.timerDuration || 600, elapsed) / 3600;
    } else if (timerState.stopwatchStatus === 'running') {
      const elapsed = Date.now() - (timerState.stopwatchStartedAt || Date.now());
      activeExtra = ((timerState.stopwatchElapsedBeforePause || 0) + elapsed) / 3600000;
    }
    return (studyLogs[todayStr]?.hours || 0) + activeExtra;
  };

