  const [obsFontSize, setObsFontSize] = useState('medium');
  const [obsBorderRadius, setObsBorderRadius] = useState('xl');
  const [obsBorderColor, setObsBorderColor] = useState('#3b82f6');
  const [obsBorderWidth, setObsBorderWidth] = useState(0);
  const [obsOpacity, setObsOpacity] = useState(100);
  const [obsShowNotes, setObsShowNotes] = useState(true);
  const [obsShowChecklist, setObsShowChecklist] = useState(true);
  const [obsShowUpcoming, setObsShowUpcoming] = useState(true);
  const [obsHideCompleted, setObsHideCompleted] = useState(false);
  const [obsTimerBackground, setObsTimerBackground] = useState('sunset');
  const [obsTimerBgTheme, setObsTimerBgTheme] = useState('gradient');

  const isObsLoadedRef = useRef(false);
  const lastSavedObsConfigRef = useRef(null);

  // OBS Customizer Settings: Load from LocalDB
  useEffect(() => {
    if (isObsOverlay) return;
    getLocalSetting('obsCustomizerConfig').then(data => {
      if (data) {
        if (data.obsSelectedWidget !== undefined) setObsSelectedWidget(data.obsSelectedWidget);
        if (data.obsTheme !== undefined) setObsTheme(data.obsTheme);
        if (data.obsBgColor !== undefined) setObsBgColor(data.obsBgColor);
        if (data.obsTextColor !== undefined) setObsTextColor(data.obsTextColor);
        if (data.obsFontSize !== undefined) setObsFontSize(data.obsFontSize);
        if (data.obsBorderRadius !== undefined) setObsBorderRadius(data.obsBorderRadius);
        if (data.obsBorderColor !== undefined) setObsBorderColor(data.obsBorderColor);
        if (data.obsBorderWidth !== undefined) setObsBorderWidth(data.obsBorderWidth);
        if (data.obsOpacity !== undefined) setObsOpacity(data.obsOpacity);
        if (data.obsShowNotes !== undefined) setObsShowNotes(data.obsShowNotes);
        if (data.obsShowChecklist !== undefined) setObsShowChecklist(data.obsShowChecklist);
        if (data.obsShowUpcoming !== undefined) setObsShowUpcoming(data.obsShowUpcoming);
        if (data.obsHideCompleted !== undefined) setObsHideCompleted(data.obsHideCompleted);
        if (data.obsTimerBackground !== undefined) setObsTimerBackground(data.obsTimerBackground);
        if (data.obsTimerBgTheme !== undefined) setObsTimerBgTheme(data.obsTimerBgTheme);

        lastSavedObsConfigRef.current = JSON.stringify(data);
      }
      isObsLoadedRef.current = true;
    }).catch(err => {
      console.error("[LocalDB] Error loading OBS customizer config:", err);
      isObsLoadedRef.current = true;
    });
  }, [isObsOverlay]);

  // OBS Customizer Settings: Persist to LocalDB
  const obsConfigSaveTimeoutRef = useRef(null);
  useEffect(() => {
    if (isObsOverlay || !isObsLoadedRef.current) return;
    const configObj = {
      obsSelectedWidget,
      obsTheme,
      obsBgColor,
      obsTextColor,
      obsFontSize,
      obsBorderRadius,
      obsBorderColor,
      obsBorderWidth,
      obsOpacity,
      obsShowNotes,
      obsShowChecklist,
      obsShowUpcoming,
      obsHideCompleted,
      obsTimerBackground,
      obsTimerBgTheme
    };
    const serialized = JSON.stringify(configObj);
    if (serialized === lastSavedObsConfigRef.current) return;

    if (obsConfigSaveTimeoutRef.current) clearTimeout(obsConfigSaveTimeoutRef.current);
    obsConfigSaveTimeoutRef.current = setTimeout(() => {
      saveLocalSetting('obsCustomizerConfig', configObj)
        .then(() => { lastSavedObsConfigRef.current = serialized; })
        .catch(err => console.error("[LocalDB] Error saving OBS customizer config:", err));
    }, 400);
    return () => {
      if (obsConfigSaveTimeoutRef.current) clearTimeout(obsConfigSaveTimeoutRef.current);
    };
  }, [
    isObsOverlay,
    obsSelectedWidget,
    obsTheme,
    obsBgColor,
    obsTextColor,
    obsFontSize,
    obsBorderRadius,
    obsBorderColor,
    obsBorderWidth,
    obsOpacity,
    obsShowNotes,
    obsShowChecklist,
    obsShowUpcoming,
    obsHideCompleted,
    obsTimerBackground,
    obsTimerBgTheme
  ]);


  // HIERARCHY STATE
  const [hierarchy, setHierarchy] = useState('');
  // deferredHierarchy: React defers expensive useMemo recomputations to background frames,
  // preventing main-thread freezes when switching large folders.
  const deferredHierarchy = useDeferredValue(hierarchy);
  const [showMobileFolderTree, setShowMobileFolderTree] = useState(false);
  const [deckPaths, setDeckPaths] = useState([]);
  const isHierarchyLoadedRef = useRef(false);
  const lastSavedDeckPathsRef = useRef(null);

  // Load initial hierarchy deckPaths from LocalDB
  useEffect(() => {
    let isMounted = true;
    getLocalSetting('hierarchy').then(data => {
      if (!isMounted) return;
      if (data?.paths && Array.isArray(data.paths)) {
        setDeckPaths(data.paths);
        lastSavedDeckPathsRef.current = JSON.stringify(data.paths);
      }
      isHierarchyLoadedRef.current = true;
    }).catch(err => {
      console.warn('[LocalDB] Error loading hierarchy paths:', err);
      isHierarchyLoadedRef.current = true;
    });
    return () => { isMounted = false; };
  }, []);

  // DERIVED EFFECTIVE DECK PATHS & AUTO-HEAL
  const effectiveDeckPaths = useMemo(() => {
    const pathsSet = new Set();
    const addPathAndAncestors = (p) => {
      if (!p || p === 'Root') return;
      const parts = p.split('::');
      let currentPath = '';
      parts.forEach(part => {
        currentPath = currentPath ? `${currentPath}::${part}` : part;
        pathsSet.add(currentPath);
      });
    };

    deckPaths.forEach(addPathAndAncestors);
    libraryPages.forEach(p => { if (p.deck) addPathAndAncestors(p.deck); });
    cards.forEach(c => { if (c.deck) addPathAndAncestors(c.deck); });
    return Array.from(pathsSet).sort();
  }, [deckPaths, libraryPages, cards]);

  useEffect(() => {
    // Skip AutoHeal until hierarchy has resolved from LocalDB and while a folder move/rename is in progress
    if (!isHierarchyLoadedRef.current || isFolderMoveInProgress.current) return;

    if (effectiveDeckPaths.length > deckPaths.length) {
      const missing = effectiveDeckPaths.filter(p => !deckPaths.includes(p));
      if (missing.length > 0) {
        const serialized = JSON.stringify(effectiveDeckPaths);
        if (serialized !== lastSavedDeckPathsRef.current) {
          console.log(`[AutoHeal] Discovered ${missing.length} unlisted folder path(s), updating Local DB settings:`, missing);
          setDeckPaths(effectiveDeckPaths);
          lastSavedDeckPathsRef.current = serialized;
          getLocalSetting('hierarchy').then(existing => {
            saveLocalSetting('hierarchy', { ...(existing || {}), paths: effectiveDeckPaths }).catch(err => console.warn('[AutoHeal] Failed to sync deckPaths:', err));
          });
        }
      }
    }
    if (effectiveDeckPaths.length > 0 && (!hierarchy || (!effectiveDeckPaths.includes(hierarchy) && hierarchy !== 'Root' && hierarchy !== 'PENDING_REVIEW' && hierarchy !== 'COMPANION_SCANS'))) {
      setHierarchy(effectiveDeckPaths[0]);
    }
  }, [effectiveDeckPaths, deckPaths, hierarchy]);

  // IMAGE PREVIEW STATE
  const [activeQueueId, setActiveQueueId] = useState(null);
  const [hoveredCardCoordinates, setHoveredCardCoordinates] = useState(null);

  const getCardBoundingBox = (card) => {
    if (!card) return null;
    if (card.ymin !== undefined && card.xmin !== undefined && card.ymax !== undefined && card.xmax !== undefined) {
      return { ymin: Number(card.ymin), xmin: Number(card.xmin), ymax: Number(card.ymax), xmax: Number(card.xmax) };
    }
    if (card.img_box) {
      if (Array.isArray(card.img_box) && card.img_box.length === 4) {
        const [ymin, xmin, ymax, xmax] = card.img_box;
        return { ymin: Number(ymin), xmin: Number(xmin), ymax: Number(ymax), xmax: Number(xmax) };
      } else if (typeof card.img_box === 'object' && card.img_box.ymin !== undefined) {
        return {
          ymin: Number(card.img_box.ymin),
          xmin: Number(card.img_box.xmin),
          ymax: Number(card.img_box.ymax),
          xmax: Number(card.img_box.xmax)
        };
      }
    }
    return null;
  };

  // MODALS
  const [editingCard, setEditingCard] = useState(null);

  // Auto-sanitize editingCard whenever it opens to strip raw base64 <img ...> tags from text/front/back
  useEffect(() => {
    if (editingCard) {
      const sanitized = sanitizeCardForEditing(editingCard);
      if (
        sanitized.text !== editingCard.text ||
        sanitized.front !== editingCard.front ||
        sanitized.back !== editingCard.back ||
        sanitized.customImage !== editingCard.customImage ||
        (sanitized.attachedImages || []).length !== (editingCard.attachedImages || []).length
      ) {
        setEditingCard(sanitized);
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [editingCard?.id]);
  const [isManualCardModalOpen, setIsManualCardModalOpen] = useState(false);
  const [manualCardInitial, setManualCardInitial] = useState(null);
