                                              const file = e.target.files[0];
                                              setPytReplacingBook(book);
                                              setPytPdfFile(file);
                                              setPytPdfMaterialName(book.name);
                                              setPytPdfMaxPages(0);
                                              setPytPdfScanStartPage("1");
                                              setPytPdfScanEndPage("Loading...");
                                              setShowPytPdfNameModal(true);
                                              const fr = new FileReader();
